## 2. Plugin Manifest Schema

Every plugin ships a `plugin.manifest.json` validated against this JSON Schema at publish time and at install time. The manifest is the *only* thing the registry and permission broker trust before code ever runs.

```jsonc
// plugin.manifest.schema.json (draft 2020-12)
{
  "$id": "https://reporting.internal/schemas/plugin-manifest/v1.json",
  "type": "object",
  "required": [
    "id", "name", "version", "apiVersion", "kind",
    "entry", "permissions", "engines"
  ],
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^[a-z0-9-]+\\.[a-z0-9-]+$",
      "description": "reverse-namespace: team-slug.plugin-slug, e.g. 'growth.salesforce-source'"
    },
    "name": { "type": "string", "maxLength": 80 },
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+(-[0-9A-Za-z.-]+)?$",
      "description": "strict semver; plugin's own release version"
    },
    "apiVersion": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+$",
      "description": "major.minor of the Host API contract this plugin targets (see §3)"
    },
    "kind": {
      "type": "array",
      "items": { "enum": ["data-source", "transform", "renderer", "exporter", "trigger"] },
      "minItems": 1
    },
    "entry": {
      "type": "object",
      "required": ["runtime", "main"],
      "properties": {
        "runtime": { "enum": ["node18", "node20", "wasm"] },
        "main": { "type": "string", "description": "relative path to entrypoint module" }
      }
    },
    "engines": {
      "type": "object",
      "required": ["host"],
      "properties": {
        "host": { "type": "string", "description": "semver range of compatible host versions, e.g. '>=4.2.0 <5.0.0'" }
      }
    },
    "permissions": {
      "type": "object",
      "description": "capability grants requested; enforced by the Permission Broker (§6.2)",
      "properties": {
        "network": {
          "type": "array",
          "items": { "type": "string", "format": "hostname-glob" },
          "description": "allow-listed outbound hosts, e.g. ['*.salesforce.com']"
        },
        "secrets": {
          "type": "array",
          "items": { "type": "string" },
          "description": "named secret refs this plugin may read from the host secret store"
        },
        "filesystem": {
          "type": "string",
          "enum": ["none", "tmp-scratch"],
          "default": "none"
        },
        "dataAccess": {
          "type": "array",
          "items": { "enum": ["report-metadata", "org-directory", "audit-log"] }
        },
        "resourceLimits": {
          "type": "object",
          "properties": {
            "memoryMb": { "type": "integer", "maximum": 1024, "default": 256 },
            "cpuMs": { "type": "integer", "description": "per-invocation CPU budget", "default": 10000 },
            "timeoutMs": { "type": "integer", "default": 30000 }
          }
        }
      },
      "additionalProperties": false
    },
    "hooks": {
      "type": "array",
      "items": { "enum": ["onLoad", "onUnload", "onConfigChange", "onHealthCheck"] },
      "description": "lifecycle hooks this plugin implements beyond the mandatory kind-specific handlers"
    },
    "configSchema": {
      "type": "object",
      "description": "JSON Schema for this plugin's own user-facing config, rendered by host admin UI"
    },
    "dependencies": {
      "type": "object",
      "additionalProperties": { "type": "string" },
      "description": "other plugin ids -> semver range, resolved by the registry (§4.3)"
    },
    "signature": {
      "type": "object",
      "required": ["algorithm", "value", "publisherKeyId"],
      "description": "detached signature over the packed artifact, verified before install (§6.1)"
    },
    "owner": {
      "type": "object",
      "required": ["team", "contact"],
      "properties": {
        "team": { "type": "string" },
        "contact": { "type": "string", "format": "email" }
      }
    }
  },
  "additionalProperties": false
}
```

Design notes:
- **`apiVersion` vs `version`** are deliberately separate: `version` is the plugin's own release, `apiVersion` pins which major.minor of the Host API contract it was built against. The host uses `apiVersion` to pick which adapter shim to expose (§3.3).
- **`permissions` is exhaustive and declarative** — no plugin can request capabilities at runtime it didn't declare at publish time. This is what makes registry review meaningful.
- **`owner`** is mandatory because five teams will own five sets of plugins; incident response needs a contact without spelunking git blame.

