        "cpuMs": {"type":"integer","default":5000},
        "timeoutMs": {"type":"integer","default":10000}
      }
    },
    "dependencies": { "type": "object", "additionalProperties": {"type":"string"}, "description": "other plugin IDs + SemVer range" },
    "signature": { "type": "string", "description": "detached signature over manifest + bundle hash" }
  }
}
```

Example:

```json
{
  "id": "export-pdf",
  "version": "1.4.0",
  "apiVersion": "^2.3.0",
  "entryPoint": "dist/index.js",
  "engine": { "runtime": "node", "runtimeVersion": "20.x" },
  "capabilities": ["report.export"],
  "permissions": { "hostServices": ["dataApi", "logApi"], "filesystem": [{"path":"/tmp/export-pdf","mode":"readwrite"}] },
  "hooks": { "onLoad": true, "onActivate": true, "onDeactivate": true },
  "resourceLimits": { "memoryMb": 256, "timeoutMs": 15000 },
  "owner": { "team": "reporting-exports", "contact": "exports-team@company.com" }
}
```

## 4. Versioned API Contract

**Principle**: the Host API is the *only* surface plugins call, versioned with SemVer independently of the host app and any plugin (major = breaking, minor = additive, patch = fix). The host serves **N and N-1 major versions concurrently** (≥2 quarters), so teams upgrade on their own schedule.

**Resolution at load**: plugin declares `apiVersion` range → host resolves the highest version in its currently-served table that satisfies it → that version's `HostApi` shape is injected into that plugin's sandbox. Two plugins can legitimately run against v1 and v2 simultaneously. No match → plugin marked `incompatible`, never loaded, surfaced in the dashboard (not a silent failure).

**Host API surface** (published as its own versioned package, e.g. `@reporting-tool/plugin-api`):

```typescript
export interface HostApi {
  readonly apiVersion: string;
  data: DataApi; storage: StorageApi; ui: UiApi; secrets: SecretsApi; log: LogApi; events: EventBus;
}
export interface DataApi {
  query(reportId: string, query: ReportQuery): Promise<ReportDataset>;
  getSchema(reportId: string): Promise<ReportSchema>;
}
export interface StorageApi { // auto-namespaced per plugin id; no cross-plugin reads
  get(key: string): Promise<unknown | undefined>;
  set(key: string, value: unknown): Promise<void>;
  delete(key: string): Promise<void>;
}
export interface UiApi {
  registerPanel(d: PanelDescriptor): void;
  registerMenuItem(d: MenuItemDescriptor): void;
  showToast(msg: string, level: "info"|"warn"|"error"): void;
}
export interface SecretsApi { get(name: string): Promise<string>; } // only names in manifest.permissions.secrets resolve
export interface LogApi { info(m:string,meta?:object):void; warn(...):void; error(...):void; }
export interface EventBus {
  on(event: HostEvent, handler: (payload: unknown) => void): Unsubscribe;
  emit(event: string, payload: unknown): void; // received by others as `plugin:<id>:<event>`
}
```

Everything is Promise-based and crosses the RPC bridge — no synchronous shared-memory path either direction (functions aren't structured-cloneable, which itself enforces the boundary).

**Deprecation**: methods marked `@deprecated since=X removeIn=Y` in the published `.d.ts`; calls are logged per calling plugin ID and surfaced on the dashboard; removal only on a major bump, only after the N-1 window elapses.

**Plugin-exported contract** (symmetric, fixed shape the host calls into):

```typescript
export interface PluginModule {
  onLoad?(ctx: PluginContext): Promise<void> | void;
  onActivate?(ctx: PluginContext): Promise<void> | void;
  onDeactivate?(ctx: PluginContext): Promise<void> | void;
  onUnload?(ctx: PluginContext): Promise<void> | void;
  onConfigChange?(ctx: PluginContext, newConfig: unknown): Promise<void> | void;
  onHealthCheck?(ctx: PluginContext): Promise<HealthStatus>;
  reportExport?: ReportExportCapability;
  reportTransform?: ReportTransformCapability;
  uiPanel?: UiPanelCapability;
}
export interface PluginContext { host: HostApi; pluginId: string; config: unknown; logger: LogApi; }
```

## 5. Lifecycle & Sandbox

**State machine**:
`DISCOVERED → REGISTERED → RESOLVED → LOADED → ACTIVE ⇄ INACTIVE → UNLOADED`, with any state able to fall into `ERRORED` (unhandled error, failed health check, timeout) → sandbox killed → restart per backoff below.

**Hook contract**:

| Hook | When | Failure behavior |
|---|---|---|
| `onLoad` | sandbox started, before first activation | → `ERRORED`, never activated |
| `onActivate` | goes live (install, host startup, post-reload) | stays `LOADED`, retried with backoff, alert after 3 failures |
| `onDeactivate` | before unload / restart-requiring config change / manual disable | logged, teardown proceeds anyway |
| `onUnload` | final teardown before sandbox kill | logged, sandbox force-killed regardless |
| `onConfigChange` | admin edits config; only if declared, else host does deactivate→unload→reload | change rejected, old config kept |
| `onHealthCheck` | polled every 30s | 3 consecutive failures → `ERRORED` → auto-restart |

**Reload isn't its own hook** — it's an orchestrated sequence: `onDeactivate → onUnload → kill sandbox → spawn new sandbox → onLoad → onActivate`. Plugins only ever implement activate/deactivate cleanly; the manager handles reload composition. Triggers: new version installed, restart-requiring config change, manual admin action.

**Sandbox boundary**: each plugin instance gets its own `worker_thread` (default) or child process (opt-in, for native addons/shell-out needs). Not an in-process VM sandbox (`vm2`/`vm`) — those share the V8 heap/event loop with the host and have a real history of sandbox-escape CVEs; a worker/process gives an actual memory and crash boundary.

- **Memory**: worker's `maxOldGenerationSizeMb` set from `resourceLimits.memoryMb`; breach kills the worker → `ERRORED`.
- **CPU**: per-call CPU-time budget (`resourceLimits.cpuMs`); runaway calls terminated, rejects `PluginTimeoutError`.
- **Wall clock**: `resourceLimits.timeoutMs` bounds every RPC round trip regardless of CPU (catches hung network waits).
- **No ambient authority**: sandbox global scope has no `fs`/`net`/`child_process`/`fetch`. All access goes through `HostApi` proxies that check `permissions` on every call.
- **Network**: only via host-mediated proxy, checked against `permissions.network` per-host allowlist; no raw sockets.
- **Filesystem**: only paths in `permissions.filesystem`, via a proxy that canonicalizes paths to block `..` traversal outside the granted root.
- **Secrets**: `secretsApi.get(name)` checked against `permissions.secrets` before anything crosses the RPC bridge — unlisted names throw, so secret material never enumerates to a compromised plugin.

**RPC bridge**: JSON-RPC 2.0 framing (`{id, method, params}` / `{id, result|error}`) over `worker_thread` structured-clone messaging or a length-prefixed JSON stream for child processes. Every call logged with `pluginId, method, durationMs, outcome`.

**Restart policy**: exponential backoff 1s → 5s → 30s → 2m → capped 10m. After 5 failures in 1 hour → auto-disable (`circuit-broken`), alert to `manifest.owner.contact`, no infinite restart hammering. Admins can force-kill/disable any plugin regardless of state.

## 6. Plugin Registry

**Responsibilities**: persist manifest + install metadata (state, health history, versions) keyed by `id`, reusing the host's existing datastore; discover installs from signed artifacts pushed by each team's CI to an internal artifact feed; validate manifest + verify signature + check `apiVersion` compatibility before handing off to the Lifecycle Manager; resolve the plugin-dependency DAG (reject on missing/incompatible deps or cycles); retain last 3 versions locally for instant rollback; expose an admin dashboard/CLI for install/upgrade/rollback/disable and visibility into health, resource usage, and deprecated-API usage per plugin.

```typescript
interface PluginRegistry {
  install(artifactRef: string, opts?: {activate?: boolean}): Promise<PluginRecord>;
  upgrade(pluginId: string, toVersion: string): Promise<PluginRecord>;
  rollback(pluginId: string, toVersion: string): Promise<PluginRecord>;
  activate(pluginId: string): Promise<void>;
  deactivate(pluginId: string): Promise<void>;
  uninstall(pluginId: string): Promise<void>;
  disable(pluginId: string, reason: string): Promise<void>;
  list(filter?: {state?: PluginState; capability?: string}): PluginRecord[];
  getHealth(pluginId: string): HealthStatus;
}
```

**Ownership split**: each of the 5 teams owns its plugin repo/CI/signing and release cadence, and its `owner` contact for alerts — they never touch the platform code. The platform team owns the `plugin-api` contract package and its deprecation schedule, the Registry/Lifecycle Manager/sandbox runtime, and a shared `create-reporting-plugin` scaffold so all 5 teams start from an identical, correct project shape instead of reinventing lifecycle boilerplate.

## 7. Observability

Structured per-call logs (`pluginId, version, method, durationMs, outcome, apiVersion`); per-plugin metrics (activation count, error rate, restart count, latency, memory high-water mark) on the existing metrics pipeline; dashboard shows state, last 20 health checks, deprecated-API calls in the last 7 days, and near-misses on resource limits; every lifecycle transition is an audit event with actor (system vs. admin).

## 8. Security Summary

| Threat | Mitigation |
|---|---|
| Cross-plugin data/secret leakage | Namespaced storage/secrets enforced host-side |
| Resource exhaustion | Worker memory cap + per-call CPU/wall-clock budgets |
| Unauthorized network access | No raw net primitives in sandbox; per-host allowlist in the proxy |
| Tampered artifact | Signature verified against team's registered key before install |
| Post-install privilege escalation | Permissions fixed at install from the signed manifest; changes require re-install |
| Crash cascade | Separate thread/process per plugin, no shared memory |
| Host upgrade breaks old plugin | `apiVersion` resolved against N/N-1 supported contract; incompatible plugins flagged, never force-loaded |

If the trust model ever extends to untrusted/external plugins, swap `worker_thread` for full OS-process isolation (seccomp/cgroups) or a WASM runtime as default `engine.runtime`, and add a manual review gate to `install()`. Out of scope this quarter.

## 9. Rollout Plan (this quarter)

1. **Wks 1–2** (platform): publish `plugin-api` v1.0.0, manifest schema, `create-reporting-plugin` scaffold; stand up Registry + Lifecycle Manager with worker_thread sandboxing behind a flag.
2. **Wks 3–4**: one pilot team ports the simplest existing integration end-to-end to shake out the contract before the rest start.
3. **Wks 5–8**: remaining 4 teams build in parallel against the now-frozen v1 contract, using the shared scaffold.
4. **Wks 9–10**: enable the dashboard for all teams, wire owner alerts, load-test restart/backoff and resource limits under real workloads.
5. **Wks 11–12**: enforce signature verification (not just log it), tune circuit-breaker thresholds from real data, run rollback drills with each team.

**Open decisions for the platform team**: which artifact registry to reuse for plugin bundle distribution; whether child_process should be the default rather than opt-in if any team needs native addons/shell-out; per-team signing keys vs. a central CI-held signing service.

