          "range": { "type": "string", "description": "semver range, e.g. '^2.1'" }
        }
      }
    },
    "runtime": {
      "type": "object",
      "required": ["kind", "isolation"],
      "properties": {
        "kind": { "enum": ["node", "wasm"] },
        "isolation": { "enum": ["worker", "subprocess", "wasm-sandbox"] },
        "resources": {
          "type": "object",
          "properties": {
            "memoryLimitMb": { "type": "integer", "default": 256 },
            "cpuQuotaPercent": { "type": "integer", "default": 50 },
