## 3. Plugin Manifest Schema

Every plugin ships a `plugin.manifest.json` validated against a published JSON Schema (`manifestSchemaVersion`). The manifest is the *only* thing the registry trusts statically — code is never introspected for capabilities.

### 3.1 Schema (JSON Schema, abbreviated)

```json
{
  "$id": "https://reporting-tool.internal/schemas/plugin-manifest-v1.json",
  "type": "object",
  "required": [
    "manifestSchemaVersion", "id", "version", "displayName",
    "publisher", "apiVersion", "entryPoints", "permissions", "resources"
  ],
  "properties": {
    "manifestSchemaVersion": { "const": 1 },

    "id": {
      "type": "string",
      "pattern": "^@[a-z0-9-]+/[a-z0-9-]+$",
      "description": "Scoped by owning team, e.g. '@team-billing/pdf-exporter'. Namespace enforced by registry ACL."
    },
    "version": { "type": "string", "format": "semver" },
    "displayName": { "type": "string" },
    "description": { "type": "string" },

    "publisher": {
      "type": "object",
      "required": ["team", "contact"],
      "properties": {
        "team": { "type": "string" },
        "contact": { "type": "string", "format": "email-or-slack-channel" }
      }
    },

    "apiVersion": {
      "type": "string",
      "description": "Semver RANGE of the Host API Contract this plugin targets, e.g. '^2.3.0'."
    },

    "entryPoints": {
      "type": "object",
      "description": "One entry per extension point this plugin contributes to. Each maps to a module path resolved inside the plugin's sandboxed runtime.",
      "properties": {
        "dataSource": { "$ref": "#/$defs/entryPoint" },
        "transform": { "$ref": "#/$defs/entryPoint" },
        "renderer": { "$ref": "#/$defs/entryPoint" },
        "exporter": { "$ref": "#/$defs/entryPoint" },
        "scheduler": { "$ref": "#/$defs/entryPoint" },
        "uiPanel": { "$ref": "#/$defs/entryPoint" }
      },
      "minProperties": 1,
      "additionalProperties": false
    },

    "permissions": {
      "type": "object",
      "description": "Explicit capability requests. Absence = denied. Reviewed by an admin at install/upgrade time; escalation on upgrade requires re-approval.",
      "properties": {
        "network": {
          "type": "array",
          "items": { "type": "string", "description": "Allowlisted host/CIDR, e.g. 'api.stripe.com'" }
        },
        "filesystem": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "scope": { "enum": ["plugin-scratch", "shared-reports-readonly", "shared-reports-write"] }
            }
          }
        },
        "dataAccess": {
          "type": "array",
          "items": { "type": "string", "description": "Named data-access scopes, e.g. 'reports:read', 'billing-dataset:read'" }
        },
        "hostApis": {
          "type": "array",
          "items": { "type": "string", "description": "Named Host API capability groups, e.g. 'reports.query', 'ui.registerPanel'" }
        }
      }
    },

    "resources": {
      "type": "object",
      "required": ["memoryLimitMb", "cpuQuotaCores", "callTimeoutMs"],
      "properties": {
        "memoryLimitMb": { "type": "integer", "maximum": 1024 },
        "cpuQuotaCores": { "type": "number", "maximum": 2 },
        "callTimeoutMs": { "type": "integer", "maximum": 30000 },
        "startupTimeoutMs": { "type": "integer", "default": 5000 }
      }
    },

    "dependencies": {
      "type": "object",
      "description": "Other plugin IDs this plugin requires to be loaded first, with semver ranges.",
      "additionalProperties": { "type": "string", "format": "semver-range" }
    },

    "configSchema": {
      "type": "object",
      "description": "JSON Schema for this plugin's own admin-configurable settings, rendered by the host's generic settings UI."
    },

    "signature": {
      "type": "object",
      "description": "Populated by the publish pipeline, not hand-authored.",
      "properties": {
        "algorithm": { "const": "ed25519" },
        "publisherKeyId": { "type": "string" },
        "value": { "type": "string" }
      }
    }
  },

  "$defs": {
    "entryPoint": {
      "type": "object",
      "required": ["module", "export"],
      "properties": {
        "module": { "type": "string" },
        "export": { "type": "string" }
      }
    }
  }
}
```

### 3.2 Example manifest

```json
{
  "manifestSchemaVersion": 1,
  "id": "@team-billing/pdf-exporter",
  "version": "1.4.2",
  "displayName": "Billing PDF Exporter",
  "publisher": { "team": "team-billing", "contact": "#team-billing-eng" },
