#!/usr/bin/env python3
"""Internal daily sensor report."""
import csv

READINGS = "readings.csv"


def load_readings(path):
    with open(path, newline="") as handle:
        return [(row["sensor"], float(row["celsius"])) for row in csv.DictReader(handle)]


def celsius_to_fahrenheit(celsius):
    return celsius * 9 / 5 + 32


def format_row(sensor, celsius):
    fahrenheit = celsius_to_fahrenheit(celsius)
    return "%-12s %6.1f C %6.1f F" % (sensor, celsius, fahrenheit)


def main():
    for sensor, celsius in load_readings(READINGS):
        print(format_row(sensor, celsius))


if __name__ == "__main__":
    main()
